package com.nextrade.engine.matching; import com.nextrade.common.enumtype.*; import com.nextrade.domain.order.Order; public enum SelfTradePrevention { CANCEL_AGGRESSOR, CANCEL_RESTING; public OrderDecision decide(Order incoming,Order resting){if(!incoming.user().id().equals(resting.user().id()))return OrderDecision.ALLOW;return this==CANCEL_AGGRESSOR?OrderDecision.CANCEL_INCOMING:OrderDecision.CANCEL_RESTING;} public enum OrderDecision{ALLOW,CANCEL_INCOMING,CANCEL_RESTING} }
